# The wrist view now shows one finger inside the front rim and one outside.
# Lower slightly, close on the rim, and perform a short lift to verify retention.
def hold_grip(arm, grip, count):
    obs = get_observation()
    s = obs['state']
    action = {'left_ee_pose': s['left_ee_pose'], 'right_ee_pose': s['right_ee_pose'], 'left_ee_joint_state': s['left_ee_joint_state'], 'right_ee_joint_state': s['right_ee_joint_state']}
    action[arm + '_ee_joint_state'] = [grip]
    for i in range(count):
        obs, reward, terminated, truncated, info = step(action)
        if terminated or truncated:
            return obs, i+1, 'ended'
    return obs, count, 'held'
r = move_ee('right', [0.25, -0.315, 0.945] + q_down, grip=0.7, max_steps=12)
report(r)
if r[2] != 'ended':
    r = hold_grip('right', 0.0, 12)
    report(r)
if r[2] != 'ended':
    report(servo_translate('right', [0.25, -0.315, 1.02], 0.0, max_steps=25))

